AND name like CONCAT(CONCAT('%',#{name}),'%')
AND status = #{status}
AND type = #{type}
AND type_id = #{typeId}
AND sort = #{sort}
order by
${orderByColumn} ${isAsc},sort_num is null,sort_num
sort desc,sort_num is null, sort_num ,crt_time desc

