where id = #{id,jdbcType=INTEGER}

mapper.select:
SELECT IFNULL(
(SELECT id FROM article WHERE sort < #{sort} and type = #{type}
ORDER BY  sort DESC LIMIT 0,1),0
) AS preTypeId

SELECT IFNULL(
(SELECT id FROM article WHERE sort > #{sort} and type = #{type}
ORDER BY  sort asc LIMIT 0,1),0
) AS nextTypeId

